import json, os
OUT="/home/hatch/workspace/divination/benchmark/phase3/runs/round88/predictions"
os.makedirs(OUT, exist_ok=True)
def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main":cm,"reserve_used":ru,"disputed":di,"reason":reason}
def B(extra):
    return "liuyao\nsystems_used: 六爻纳甲\n"+extra
def W(cid, pred, basis, conf, trig):
    rec={"case_id":cid,"prediction_text":pred,"basis":basis,"confidence":conf,"trigger":trig}
    p=os.path.join(OUT,cid+".json")
    with open(p,"w",encoding="utf-8") as f: json.dump(rec,f,ensure_ascii=False,indent=1)
    d=json.load(open(p,encoding="utf-8"))
    assert set(d)== {"case_id","prediction_text","basis","confidence","trigger"}, cid
    assert d["case_id"]==cid and 0<=d["confidence"]<=1, cid
    assert all(isinstance(d["trigger"][k],bool) for k in ("changed_main","reserve_used","disputed")), cid
    return os.path.getsize(p)

